package ru.akvine.zond.models;

import com.github.javaparser.StaticJavaParser;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

class GeneratedSourcesTest {

    @Test
    void annotationAndHeaderCommentMarkGeneratedCode() {
        assertThat(generated("""
                @Generated("protoc")
                public class Order {
                }
                """)).isTrue();
        assertThat(generated("""
                // Generated by the protocol buffer compiler.  DO NOT EDIT!
                public final class OrderProto {
                }
                """)).isTrue();
        assertThat(generated("""
                public class Order {
                    // generated by hand, a long time ago
                    void pay() {
                    }
                }
                """)).isFalse();
    }

    @Test
    void myBatisGeneratorClassesWithoutCommentsAreGenerated() {
        assertThat(generated("""
                public class OrderExample {
                    protected abstract static class GeneratedCriteria {
                    }
                    public static class Criteria extends GeneratedCriteria {
                    }
                }
                """)).isTrue();
        assertThat(generated("""
                public interface OrderMapper {
                    long countByExample(OrderExample example);
                    int deleteByPrimaryKey(Long id);
                    int insertSelective(Order row);
                    List<Order> selectByExample(OrderExample example);
                    Order selectByPrimaryKey(Long id);
                }
                """)).isTrue();
        assertThat(generated("""
                public class Order implements Serializable {
                    private Long id;
                    @Override
                    public String toString() {
                        StringBuilder sb = new StringBuilder();
                        sb.append(getClass().getSimpleName());
                        sb.append(" [");
                        sb.append("Hash = ").append(hashCode());
                        sb.append(", id=").append(id);
                        sb.append("]");
                        return sb.toString();
                    }
                }
                """)).isTrue();
    }

    @Test
    void ownMapperWithFewGeneratorNamesIsNotGenerated() {
        // Свой интерфейс, где совпали имена insert и selectByPrimaryKey, и свой метод рядом с ними
        assertThat(generated("""
                public interface OrderDao {
                    int insert(Order order);
                    Order selectByPrimaryKey(Long id);
                }
                """)).isFalse();
        assertThat(generated("""
                public interface OrderMapper {
                    long countByExample(OrderExample example);
                    int deleteByPrimaryKey(Long id);
                    int insertSelective(Order row);
                    Order selectByPrimaryKey(Long id);
                    List<Order> findOverdue(LocalDate date);
                }
                """)).isFalse();
    }

    private boolean generated(String code) {
        return GeneratedSources.isGenerated(StaticJavaParser.parse(code));
    }
}
